import datetime
from itertools import chain
from typing import Union, Tuple

from six import PY2, string_types, ensure_text
from taf.transport.ssh import ssh, ConnectFailedError

from .commons import LOGGER


def id_gen(upper_limit):
    i = 0
    while True:
        yield i
        i += 1
        if i == upper_limit:
            i = 0


_u32_max = 4294967295
context_id = id_gen(_u32_max)
procedure_id = id_gen(_u32_max)


def get_context_id():
    return next(context_id)


def get_procedure_id():
    return next(procedure_id)


def get_timestamp():
    return str(datetime.datetime.now())


def hexdump(src, length=16):
    """
    Adapted from http://codepad.org/ekfw3UZg
    """
    try:
        src = src.decode()
    except AttributeError:
        pass
    filter_ = ''.join([(len(repr(chr(x))) == 3) and chr(x) or '.' for x in range(256)])
    lines = []
    for c in range(0, len(src), length):
        chars = src[c:c + length]
        hex_val = ' '.join(['{:02x}'.format(ord(x)) for x in chars])
        printable = ''.join(["{}".format((ord(x) <= 127 and filter_[ord(x)]) or '.') for x in chars])
        lines.append('{:04x}  {:<{align}}  {}\n'.format(c, hex_val, printable, align=length * 3))
    return ''.join(lines)


def flatten_list(list2d):
    return list(chain(*list2d))


def chunks(array, n):
    """Yield successive n-sized chunks from array"""
    for i in range(0, len(array), n):
        yield array[i:i + n]


def intlify(*nums):
    return tuple(int(n, 16) if isinstance(n, string_types) and '0x' in n
                 else int(n)
                 for n in nums)


def get_full_cpu_id(board, cpu):
    # type: (int, int) -> str
    """
    Merge board id with cpu id, e.g., for board=0x12 and cpu=0x32 return '0x1232'
    """
    return hex(board) + hex(cpu)[2:]


def coroutine(func):
    def start(*args, **kwargs):
        cr = func(*args, **kwargs)
        next(cr)
        return cr
    return start


def compare_messages(msg1, msg2):
    for fname, _ in msg1._fields_:
        if fname == 'header':
            continue
        print('{}: {} {}'.format(fname, getattr(msg1, fname), getattr(msg2, fname)))


def memoize(f):
    """
    Memoization decorator for a function taking one or more arguments.
    http://code.activestate.com/recipes/578231-probably-the-fastest-memoization-decorator-in-the-/
    """
    class Memodict(dict):
        def __getitem__(self, *key):
            return super(Memodict, self).__getitem__(key)

        def __missing__(self, key):
            ret = self[key] = f(*key)
            return ret

    return Memodict().__getitem__


def get_hw_version():  # noqa: C901
    # type: () -> Tuple[str, str]
    msm_ip = '192.168.255.129'
    esm_ips = ('fct-4a', '192.168.255.7')
    cmd = 'cat /proc/device-tree/module-identity/unit-id'

    msm = None
    esm = None

    def _get_hw_version(smod_type):
        versions_dict = {'FSMF': 'FSMr3', 'FSIH': 'FSMr3',
                         'ASIA': 'FSMr4', 'ASIB': 'FSMr4', 'FSIP': 'FSMr4', 'ABIA': 'FSMr4',
                         'ASIK': 'FSMr5', 'ABIL': 'FSMr5', 'ASOD': 'FSMr5',
                         'ASIL': 'FSMr6', 'ASOE': 'FSMr6', 'ASOF': 'FSMr6', 'ABIN': 'FSMr6', 'ABIO': 'FSMr6',
                         'ASIM': 'FSMr7', 'ABIP': 'FSMr7', 'ASOG': 'FSMr7', 'ASOH': 'FSMr7'}

        smod_type = ensure_text(smod_type).strip('\x00')
        smod_version = versions_dict.get(smod_type, '?')
        LOGGER.debug('Detected SMOD type: {} ({})'.format(smod_type, smod_version))
        # TODO these returned values are inacurate/misleading cause we're actually interested
        # in the DSP pool, not in SMOD versions, but it is what it is, at least for now
        if int(smod_version.replace('FSMr', '')) >= 4:
            return 'FSMr4'
        else:
            return 'FSMr3'

    s = ssh()
    username = 'toor4nsn'
    password = 'oZPS0POrRieRtu'

    try:
        connection_msm = s.connect_to(msm_ip, username, password=password, timeout=15)
        output = connection_msm.execute(cmd)
        msm = _get_hw_version(output)
    except ConnectFailedError:
        msg = ('Could not determine HW version of MSM. Check if SSH connection to BTS is enabled, '
               'particularly that `systemAcctPermEnable` is set to `false` in SCF.')
        raise RuntimeError(msg)

    connection_esm = None
    for esm_ip in esm_ips:
        LOGGER.debug('Trying ESM at {}'.format(esm_ip))
        try:
            connection_esm = s.connect_to(esm_ip, username, password=password, proxy=connection_msm, timeout=15)
            output = connection_esm.execute(cmd)
            esm = _get_hw_version(output)
            break
        except ConnectFailedError:
            pass

    if connection_esm and connection_esm.is_connected:
        connection_esm.disconnect()
    if connection_msm and connection_msm.is_connected:
        connection_msm.disconnect()

    return msm, esm


def bytearray_(bytearray_or_byte_string):
    # type: (Union[str, bytearray]) -> bytearray

    # If is already bytearray -> return as is
    if isinstance(bytearray_or_byte_string, bytearray):
        return bytearray_or_byte_string

    # now it's str / bytes
    if PY2 or not isinstance(bytearray_or_byte_string, string_types):
        return bytearray(bytearray_or_byte_string)

    return bytearray(bytearray_or_byte_string, 'ISO-8859-1')


def bytes_(bytearray_or_byte_string):
    # type: (Union[str, bytearray]) -> bytes
    if isinstance(bytearray_or_byte_string, bytearray):
        return bytes(bytearray_or_byte_string)

    if PY2 or not isinstance(bytearray_or_byte_string, string_types):
        return bytes(bytearray_or_byte_string)

    return bytes(bytearray_or_byte_string, 'ISO-8859-1')
